style.css:
@-moz-document domain("open.spotify.com") {
/* Main background */
html, body,
#main,
.main-view,
.Root__main-view,
[data-testid="home-page"] {
    background: #eeecec !important;
    color: #555252 !important;
}

/* Sidebar */
nav,
aside,
[data-testid="left-sidebar"] {
    background: #e7e5e5 !important;
    color: #666 !important;
}

/* Top bar */
header,
[data-testid="topbar"] {
    background: #eeecec !important;
}

/* Playlist and album cards */
[data-testid="card"],
.card,
.main-card {
    background: #e4e2e2 !important;
    border-radius: 16px !important;
    box-shadow: 0 4px 16px rgba(255,255,255,.65),
                0 2px 8px rgba(180,180,180,.18) !important;
}

/* Buttons */
button,
[role="button"] {
    border-radius: 12px !important;
}

/* Search box */
input,
[data-testid="search-input"] {
    background: #e5e3e3 !important;
    border: 1px solid #f7f6f6 !important;
    color: #777 !important;
    border-radius: 20px !important;
}

/* Text */
h1, h2, h3, p,
span, a {
    color: inherit;
}

/* Player bar */
footer,
[data-testid="now-playing-bar"] {
    background: #e9e7e7 !important;
    border-top: 1px solid #f8f7f7 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-thumb {
    background: #d0cece;
    border-radius: 20px;
}

::-webkit-scrollbar-track {
    background: #eeecec;
}

/* Selected sidebar items */
[aria-current="page"] {
    background: #dedcdc !important;
    border-radius: 12px !important;
}

/* Subtle monochrome buttons */
button:hover,
[role="button"]:hover {
    filter: brightness(1.04);
    transition: .3s ease;
}
}
